  const ENDPOINT = '/api/analytics';
  const DEBOUNCE_MS = 500;
  const MAX_WAIT_MS = 5000;
  const MAX_BATCH_SIZE = 50;
  const MAX_QUEUE_SIZE = 100;
  let queue = [];
  let debounceTimer;
  let deadlineTimer;
  let inFlight = 0;·
  function clearTimers() {
    clearTimeout(debounceTimer);
    clearTimeout(deadlineTimer);
    debounceTimer = undefined;
    deadlineTimer = undefined;
  }·
  function schedule() {
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => flush(), DEBOUNCE_MS);
    // Continuous activity must not postpone a batch indefinitely.
    if (deadlineTimer === undefined) {
      deadlineTimer = setTimeout(() => flush(), MAX_WAIT_MS);
    }
  }·
  function track(type, details = {}) {
    // Bound memory while a request is slow or the collector is unavailable.
    if (queue.length >= MAX_QUEUE_SIZE) return;
    queue.push({ type, timestamp: new Date().toISOString(), path: location.pathname, ...details });
    schedule();
  }·
  function flush(leaving = false) {
    clearTimers();
    if (!queue.length || (inFlight > 0 && !leaving)) return;·
    const events = queue.splice(0, MAX_BATCH_SIZE);
    const body = JSON.stringify({ events });
    if (leaving) {
      try {
        if (navigator.sendBeacon?.(ENDPOINT, new Blob([body], { type: 'application/json' }))) {
          if (queue.length) flush(true);
          return;
        }
      } catch {
        // A rejected beacon falls back to a keepalive request.
      }
    }·
    inFlight += 1;
    // Best effort: never block navigation or retry into an unavailable server.
    Promise.resolve()
      .then(() => fetch(ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body,
        keepalive: true,
        credentials: 'omit',
      }))
      .catch(() => {})
      .finally(() => {
        inFlight -= 1;
        if (queue.length) schedule();
      });·
    if (leaving && queue.length) flush(true);
  }·
