    const target = event.target instanceof Element ? event.target : null;
    if (!target) return;
    const element = target.closest('a, button, [role=\"button\"]') || target;
    const details = { tag: element.tagName.toLowerCase() };
    const href = element.getAttribute('href');
    if (href) {
